}

/* =====================================================================
   Not found
   ===================================================================== */
export function GlassNotFound({ code = "404", title = "This page wandered off", text = "The link may be old, or the page has moved.", art, actions, className = "" }) {
  return (
    <section className={"gnf " + className} aria-labelledby="gnf-t">
      <div className="gnf-code" aria-hidden="true">{code.split("").map((c, k) => <span key={k} style={{ "--k": k }}>{c === "0" && art ? <span className="gnf-art">{art}</span> : c}</span>)}</div>
      <h2 id="gnf-t">{title}</h2>
      <p>{text}</p>
      {actions && <div className="gnf-acts">{actions}</div>}
    </section>
  );
}

:is(.gcp, .gft, .gptr, .ghh, .gms, .goa, .gsc, .gmy, .gnf, .gcy, .giv, .gthm) {
  --x-card: #fff; --x-fg: var(--glass-fg, #17171a); --x-muted: rgb(var(--glass-shadow, 23 23 26) / 0.56); --x-faint: rgb(var(--glass-shadow, 23 23 26) / 0.07); --x-line: rgb(var(--glass-shadow, 23 23 26) / 0.12);
  --x-r: clamp(10px, var(--glass-radius, 14px), 18px); --x-accent: var(--glass-tint, #2f6df6); --x-on: var(--glass-on-tint, #fff);
}
:root[data-glass-mode="dark"] :is(.gcp, .gft, .gptr, .ghh, .gms, .goa, .gsc, .gmy, .gnf, .gcy, .giv, .gthm) { --x-card: #1d1d22; --x-fg: #f3f3f6; --x-muted: rgb(255 255 255 / 0.58); --x-faint: rgb(255 255 255 / 0.07); --x-line: rgb(255 255 255 / 0.12); }
.gx-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

/* Colour picker */
.gcp { display: grid; grid-template-columns: minmax(0, 1fr); gap: 12px; width: 100%; max-width: 280px; padding: 14px; border-radius: 20px; color: var(--x-fg); background: var(--x-card); box-shadow: 0 0 0 0.5px var(--x-line), 0 18px 36px -24px rgb(0 0 0 / 0.45); box-sizing: border-box; }
.gcp-sq { position: relative; height: 170px; border-radius: 12px; background-image: linear-gradient(0deg, #000, transparent), linear-gradient(90deg, #fff, transparent) !important; background-blend-mode: normal; cursor: crosshair; touch-action: none; outline: none; }
.gcp-sq { background-image: linear-gradient(0deg, #000, transparent), linear-gradient(90deg, #fff, rgb(255 255 255 / 0)); }
.gcp-hue { position: relative; height: 14px; border-radius: 99px; background: linear-gradient(90deg, #f00, #ff0, #0f0, #0ff, #00f, #f0f, #f00); cursor: pointer; touch-action: none; outline: none; }
.gcp-knob { position: absolute; top: 50%; width: 18px; height: 18px; margin: -9px 0 0 -9px; border-radius: 50%; box-shadow: 0 0 0 3px #fff, 0 2px 8px rgb(0 0 0 / 0.35); pointer-events: none; transition: transform 0.15s; }
.gcp-sq .gcp-knob { top: 0; margin-top: -9px; }
.gcp-sq:focus-visible .gcp-knob, .gcp-hue:focus-visible .gcp-knob { transform: scale(1.25); box-shadow: 0 0 0 3px #fff, 0 0 0 5px var(--x-accent); }
.gcp-row { display: flex; align-items: center; gap: 8px; }
.gcp-now { flex: none; width: 36px; height: 36px; border-radius: 10px; box-shadow: inset 0 0 0 1px rgb(0 0 0 / 0.1); }
.gcp-hex { display: flex; align-items: center; gap: 6px; flex: 1; min-width: 0; height: 36px; padding: 0 10px; border-radius: 10px; background: var(--x-faint); font-size: 12px; color: var(--x-muted); }
.gcp-hex input { flex: 1; min-width: 0; border: 0; outline: none; font: 500 14px ui-monospace, "SF Mono", Menlo, monospace; text-transform: uppercase; color: var(--x-fg); background: none; }
.gcp-drop { display: grid; place-items: center; flex: none; width: 36px; height: 36px; padding: 0; border: 0; border-radius: 10px; color: var(--x-fg); background: var(--x-faint); cursor: pointer; }
.gcp-sw { display: flex; flex-wrap: wrap; gap: 7px; }
.gcp-sw button { width: 24px; height: 24px; padding: 0; border: 0; border-radius: 50%; cursor: pointer; box-shadow: inset 0 0 0 1px rgb(0 0 0 / 0.12); transition: transform 0.2s cubic-bezier(0.3, 1.6, 0.5, 1); }
.gcp-sw button:hover { transform: scale(1.15); }
.gcp-sw button[aria-checked="true"] { box-shadow: 0 0 0 2px var(--x-card), 0 0 0 4px var(--x-fg); }

/* Image viewer */
.giv { display: grid; grid-template-columns: repeat(var(--cols), 1fr); gap: 8px; width: 100%; max-width: 420px; }
.giv-th { aspect-ratio: 1; padding: 0; overflow: hidden; border: 0; border-radius: 12px; background: var(--x-faint); cursor: zoom-in; }
.giv-th img { display: block; width: 100%; height: 100%; object-fit: cover; transition: transform 0.4s cubic-bezier(0.3, 1.2, 0.4, 1); }
.giv-th:hover img { transform: scale(1.06); }
.giv-th:focus-visible { outline: 2px solid var(--x-accent); outline-offset: 2px; }
.giv-full { position: fixed; inset: 0; z-index: 2000; display: grid; }
.giv-back { position: absolute; inset: 0; background: rgb(8 8 12 / 0.9); animation: gv-fade 0.3s; }
@keyframes gv-fade { from { opacity: 0; } }
.giv-stage { position: absolute; inset: 56px 16px 64px; display: grid; place-items: center; touch-action: pan-y; }
.giv-img { display: block; max-width: min(100%, 1100px); max-height: calc(100vh - 140px); max-height: calc(100dvh - 140px); object-fit: contain; border-radius: 10px; transform-origin: 0 0; transition: transform 0.45s cubic-bezier(0.3, 1.1, 0.4, 1); user-select: none; box-shadow: 0 30px 80px -30px rgb(0 0 0 / 0.8); cursor: zoom-in; }
.giv-img[data-zoom] { transform: scale(1.8) !important; transform-origin: 50% 50%; cursor: zoom-out; }
.giv-bar { position: absolute; left: 0; right: 0; top: 0; display: flex; align-items: center; gap: 10px; padding: 12px 14px; color: #fff; }
.giv-count { font-size: 13px; font-weight: 600; font-variant-numeric: tabular-nums; }
.giv-cap { flex: 1; font-size: 13px; opacity: 0.75; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.giv-count + .giv-b { margin-left: auto; }
.giv-b, .giv-nav { display: grid; place-items: center; width: 40px; height: 40px; padding: 0; border: 0; border-radius: 50%; color: #fff; background: rgb(255 255 255 / 0.14); cursor: pointer; }
.giv-nav { position: absolute; top: 50%; margin-top: -20px; }
.giv-prev { left: 14px; } .giv-next { right: 14px; }
@media (max-width: 600px) { .giv-nav { top: auto; bottom: 14px; margin: 0; } .giv-prev { left: calc(50% - 50px); } .giv-next { right: calc(50% - 50px); } }

/* File tree */
.gft { width: 100%; max-width: 300px; margin: 0; padding: 6px; list-style: none; border-radius: 16px; color: var(--x-fg); background: var(--x-card); box-shadow: 0 0 0 0.5px var(--x-line), 0 14px 30px -22px rgb(0 0 0 / 0.4); font-size: 13.5px; }
.gft li { display: flex; align-items: center; gap: 4px; height: 30px; padding: 0 8px 0 calc(6px + var(--d) * 16px); border-radius: 8px; cursor: pointer; outline: none; user-select: none; animation: gft-in 0.25s cubic-bezier(0.3, 1.2, 0.4, 1); }
