.gft li[aria-selected="true"] .gft-chev, .gft li[aria-selected="true"] .gft-ic { color: inherit !important; }
.gft-ic { display: inline-flex; flex: none; color: var(--x-muted); }
.gft-name { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.gft-badge { font: 600 11px ui-monospace, "SF Mono", Menlo, monospace; color: #c27c00; }
.gft-badge[data-tone="new"] { color: #1f9d55; }

/* Marquee */
.gmq { width: 100%; overflow: hidden; -webkit-mask-image: linear-gradient(90deg, transparent, #000 10%, #000 90%, transparent); mask-image: linear-gradient(90deg, transparent, #000 10%, #000 90%, transparent); }
.gmq-track { display: flex; width: max-content; animation: gmq var(--dur) linear infinite; animation-direction: var(--dir); }
.gmq[data-pause]:hover .gmq-track, .gmq[data-pause]:focus-within .gmq-track { animation-play-state: paused; }
@keyframes gmq { to { transform: translateX(-50%); } }
.gmq-row { display: flex; align-items: center; gap: var(--gap); padding-right: var(--gap); }
.gmq-item { flex: none; }

/* Tilt card */
.gtlt { perspective: 900px; }
.gtlt-in { position: relative; transform: rotateX(var(--rx, 0)) rotateY(var(--ry, 0)) scale(var(--s, 1)); transition: transform 0.5s cubic-bezier(0.3, 1.2, 0.4, 1); transform-style: preserve-3d; border-radius: inherit; }
.gtlt[data-on="1"] .gtlt-in { transition-duration: 0.12s; }
.gtlt-glare { position: absolute; inset: 0; border-radius: inherit; pointer-events: none; opacity: 0; background: radial-gradient(circle at var(--gx, 50%) var(--gy, 50%), rgb(255 255 255 / 0.35), transparent 55%); mix-blend-mode: soft-light; transition: opacity 0.3s; }
.gtlt[data-on="1"] .gtlt-glare { opacity: 1; }

/* Pull to refresh */
.gptr { position: relative; width: 100%; max-width: 340px; overflow: hidden; border-radius: 26px; color: var(--x-fg); background: var(--x-card); box-shadow: 0 0 0 0.5px var(--x-line), 0 20px 40px -26px rgb(0 0 0 / 0.45); }
.gptr-ind { position: absolute; left: 0; right: 0; top: 0; display: flex; align-items: center; justify-content: center; gap: 8px; overflow: hidden; font-size: 12.5px; color: var(--x-muted); }
.gptr-spin { display: inline-flex; color: var(--x-accent); }
.gptr-spin[data-busy] { animation: gptr-spin 0.8s linear infinite; }
@keyframes gptr-spin { to { transform: rotate(360deg); } }
.gptr-scroll { height: 100%; overflow-y: auto; overscroll-behavior: contain; transition: transform 0.45s cubic-bezier(0.3, 1.3, 0.4, 1); background: var(--x-card); user-select: none; }

/* Cylinder carousel */
.gcy { width: 100%; outline: none; }
.gcy:focus-visible .gcy-stage { box-shadow: 0 0 0 2px var(--x-accent); border-radius: 20px; }
.gcy-stage { display: grid; place-items: center; perspective: 1100px; cursor: grab; touch-action: pan-y; user-select: none; overflow: hidden; }
.gcy-stage:active { cursor: grabbing; }
.gcy-drum { position: relative; transform-style: preserve-3d; transition: transform 0.65s cubic-bezier(0.3, 1.1, 0.35, 1); }
.gcy-drum[data-drag] { transition: none; }
.gcy-card { position: absolute; inset: 0; overflow: hidden; border-radius: 18px; backface-visibility: hidden; box-shadow: 0 20px 40px -20px rgb(0 0 0 / 0.45); filter: brightness(0.75); transition: filter 0.4s; }
.gcy-card[data-on] { filter: none; }
.gcy-ctl { display: flex; align-items: center; justify-content: center; gap: 14px; margin-top: 4px; font-size: 13px; font-weight: 600; color: var(--x-muted); font-variant-numeric: tabular-nums; }
.gcy-ctl button { display: grid; place-items: center; width: 36px; height: 36px; padding: 0; border: 0; border-radius: 50%; color: var(--x-fg); background: var(--x-faint); cursor: pointer; }

/* Theme toggle */
.gthm { display: grid; place-items: center; padding: 0; border: 0; border-radius: 50%; color: #f4a01a; background: #fff3d6; cursor: pointer; transition: background 0.5s, color 0.5s, transform 0.2s; box-shadow: inset 0 0 0 1px rgb(0 0 0 / 0.06); }
.gthm:active { transform: scale(0.92); }
.gthm[data-dark] { color: #c9c6ff; background: #22204a; }
.gthm svg { overflow: visible; transition: transform 0.6s cubic-bezier(0.3, 1.4, 0.5, 1); }
.gthm[data-dark] svg { transform: rotate(40deg); }
.gthm-body { transition: r 0.5s cubic-bezier(0.3, 1.4, 0.5, 1); }
.gthm-bite { transition: cx 0.5s cubic-bezier(0.3, 1.2, 0.5, 1), cy 0.5s cubic-bezier(0.3, 1.2, 0.5, 1); }
.gthm-rays { transform-origin: 12px 12px; transition: transform 0.5s cubic-bezier(0.3, 1.4, 0.5, 1), opacity 0.3s; }
.gthm[data-dark] .gthm-rays { transform: scale(0.4) rotate(-45deg); opacity: 0; }
.gthm:focus-visible { outline: 2px solid var(--x-accent); outline-offset: 3px; }

/* Hover highlight */
.ghh { position: relative; display: inline-flex; gap: 2px; padding: 4px; border-radius: 16px; color: var(--x-fg); background: var(--x-card); box-shadow: 0 0 0 0.5px var(--x-line), 0 10px 24px -18px rgb(0 0 0 / 0.4); }
.ghh[data-dir="column"] { flex-direction: column; min-width: 200px; }
.ghh-pill { position: absolute; left: 0; top: 0; border-radius: 11px; background: var(--x-faint); pointer-events: none; transition: transform 0.35s cubic-bezier(0.3, 1.2, 0.4, 1), width 0.35s cubic-bezier(0.3, 1.2, 0.4, 1), height 0.35s, opacity 0.2s; }
.ghh button { position: relative; display: inline-flex; align-items: center; gap: 8px; height: 38px; padding: 0 14px; border: 0; border-radius: 11px; font: inherit; font-size: 14px; font-weight: 500; color: var(--x-muted); background: none; cursor: pointer; transition: color 0.2s; }
.ghh button[data-on] { color: var(--x-fg); font-weight: 600; }
.ghh button:hover { color: var(--x-fg); }
.ghh button[data-on]::after { content: ""; position: absolute; left: 14px; right: 14px; bottom: 4px; height: 2px; border-radius: 2px; background: var(--x-accent); }
.ghh[data-dir="column"] button { justify-content: flex-start; }
.ghh[data-dir="column"] button[data-on]::after { left: 4px; right: auto; top: 10px; bottom: 10px; width: 3px; height: auto; }
.ghh button:focus-visible { outline: 2px solid var(--x-accent); outline-offset: -2px; }

/* Morphing search */
.gms { position: relative; }
.gms-bar { display: flex; align-items: center; width: 46px; height: 46px; overflow: hidden; border-radius: 99px; color: var(--x-fg); background: var(--x-card); box-shadow: 0 0 0 0.5px var(--x-line), 0 10px 24px -16px rgb(0 0 0 / 0.4); transition: width 0.5s cubic-bezier(0.3, 1.15, 0.4, 1); }
.gms[data-open] .gms-bar { width: var(--w); }
.gms-ic { display: grid; place-items: center; flex: none; width: 46px; height: 46px; padding: 0; border: 0; border-radius: 50%; color: inherit; background: none; cursor: pointer; }
.gms-bar input { flex: 1; min-width: 0; height: 100%; border: 0; outline: none; font: inherit; font-size: 15px; color: inherit; background: none; opacity: 0; transition: opacity 0.2s; }
.gms[data-open] .gms-bar input { opacity: 1; transition-delay: 0.15s; }
.gms-x { display: grid; place-items: center; flex: none; width: 32px; height: 32px; margin-right: 7px; padding: 0; border: 0; border-radius: 50%; color: var(--x-muted); background: var(--x-faint); cursor: pointer; }
.gms-k { position: absolute; right: -26px; top: 13px; padding: 2px 6px; border-radius: 6px; font: 600 11px ui-monospace, "SF Mono", Menlo, monospace; color: var(--x-muted); box-shadow: inset 0 0 0 1px var(--x-line); }
.gms-list { position: absolute; z-index: 30; left: 0; width: var(--w); top: calc(100% + 8px); margin: 0; padding: 6px; list-style: none; border-radius: 16px; color: var(--x-fg); background: var(--x-card); box-shadow: 0 0 0 0.5px var(--x-line), 0 18px 40px -16px rgb(0 0 0 / 0.4); box-sizing: border-box; }
.gms-list li { display: flex; justify-content: space-between; align-items: center; gap: 10px; min-height: 40px; padding: 0 12px; border-radius: 10px; font-size: 14px; cursor: pointer; animation: gms-in 0.3s cubic-bezier(0.3, 1.2, 0.4, 1) calc(var(--i) * 30ms) backwards; }
@keyframes gms-in { from { opacity: 0; transform: translateY(-4px); } }
.gms-list li[aria-selected="true"] { background: var(--x-faint); }
.gms-list em { font-style: normal; font-size: 12px; color: var(--x-muted); }

/* Overflow actions */
.goa { position: relative; display: flex; align-items: center; gap: 6px; width: 100%; min-width: 0; }
.goa-meas { position: absolute; left: 0; top: 0; width: 0; height: 0; overflow: hidden; visibility: hidden; pointer-events: none; display: flex; gap: 6px; white-space: nowrap; }
.goa-b { display: inline-flex; align-items: center; gap: 7px; flex: none; height: 38px; padding: 0 14px; border: 0; border-radius: 12px; font: inherit; font-size: 13.5px; font-weight: 500; white-space: nowrap; color: var(--x-fg); background: var(--x-faint); cursor: pointer; }
.goa-b[data-danger] { color: #e5484d; }
.goa-dots { width: 40px; padding: 0; justify-content: center; }
.goa-more { position: relative; }
.goa-menu { position: absolute; z-index: 30; right: 0; top: calc(100% + 6px); display: grid; min-width: 180px; padding: 5px; border-radius: 14px; color: var(--x-fg); background: var(--x-card); box-shadow: 0 0 0 0.5px var(--x-line), 0 18px 40px -16px rgb(0 0 0 / 0.4); animation: gms-in 0.25s cubic-bezier(0.3, 1.2, 0.4, 1); }
.goa-menu button { display: flex; align-items: center; gap: 9px; min-height: 36px; padding: 0 10px; border: 0; border-radius: 9px; font: inherit; font-size: 14px; text-align: left; color: inherit; background: none; cursor: pointer; }
.goa-menu button:hover { background: var(--x-faint); }
.goa-menu button[data-danger] { color: #e5484d; }
:root[data-glass-mode="dark"] .goa { --x-card: #1d1d22; --x-fg: #f3f3f6; --x-faint: rgb(255 255 255 / 0.08); }

/* Card folder */
.gcf { --fc: #6d8cff; position: relative; display: block; width: 200px; height: 150px; padding: 0; border: 0; background: none; cursor: pointer; perspective: 600px; }
.gcf-back { position: absolute; inset: 14px 0 0; border-radius: 6px 16px 16px 16px; background: color-mix(in srgb, var(--fc) 75%, #000); }
.gcf-back::before { content: ""; position: absolute; left: 0; top: -12px; width: 76px; height: 20px; border-radius: 8px 10px 0 0; background: inherit; }
.gcf-card { position: absolute; left: 50%; top: 24px; width: 120px; height: 84px; margin-left: -60px; overflow: hidden; border-radius: 10px; background: #fff; box-shadow: 0 6px 16px -6px rgb(0 0 0 / 0.35); transform: translateY(14px) rotate(calc(var(--k) * 3deg)); transition: transform 0.5s cubic-bezier(0.3, 1.4, 0.5, 1); z-index: var(--z); }
.gcf[data-open] .gcf-card { transform: translate(calc(var(--k) * 58px), calc(-46px + var(--k) * var(--k) * 10px)) rotate(calc(var(--k) * 12deg)); }
.gcf-front { position: absolute; left: 0; right: 0; bottom: 0; z-index: 5; display: flex; flex-direction: column; justify-content: flex-end; height: 92px; padding: 12px 14px; border-radius: 14px; text-align: left; color: #fff;
  background: linear-gradient(180deg, color-mix(in srgb, var(--fc) 92%, #fff), var(--fc)); box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.35), 0 10px 20px -12px rgb(0 0 0 / 0.5); transform-origin: 50% 100%; transition: transform 0.5s cubic-bezier(0.3, 1.3, 0.5, 1); }
.gcf[data-open] .gcf-front { transform: rotateX(-24deg); }
.gcf-name { font-size: 15px; font-weight: 650; } .gcf-meta { font-size: 12px; opacity: 0.85; }
.gcf:focus-visible { outline: 2px solid var(--glass-tint, #2f6df6); outline-offset: 6px; border-radius: 16px; }

/* Availability */
.gsc { width: 100%; max-width: 440px; }
.gsc-grid { display: grid; grid-template-columns: auto repeat(var(--days), 1fr); gap: 4px; user-select: none; touch-action: none; }
.gsc-day { padding-bottom: 4px; text-align: center; font-size: 12px; font-weight: 600; color: var(--x-muted); }
.gsc-time { padding-right: 6px; font-size: 11px; line-height: 26px; text-align: right; white-space: nowrap; color: var(--x-muted); }
.gsc-cell { height: 26px; padding: 0; border: 0; border-radius: 6px; background: var(--x-faint); cursor: pointer; transition: background 0.15s, transform 0.2s cubic-bezier(0.3, 1.6, 0.5, 1); }
.gsc-cell:hover { background: var(--x-line); }
.gsc-cell[aria-pressed="true"] { background: var(--x-accent); transform: scale(1.04); }
.gsc-cell:focus-visible { outline: 2px solid var(--x-accent); outline-offset: 1px; }
.gsc-sum { margin: 10px 0 0; text-align: center; font-size: 13px; color: var(--x-muted); }

/* Masonry */
.gmy { width: 100%; overflow-y: auto; border-radius: 20px; overscroll-behavior: contain; }
.gmy-cols { display: flex; gap: var(--gap); }
.gmy-col { display: flex; flex: 1; flex-direction: column; gap: var(--gap); min-width: 0; }
.gmy-item { overflow: hidden; border-radius: 14px; animation: gmy-in 0.5s cubic-bezier(0.3, 1.2, 0.4, 1); }
@keyframes gmy-in { from { opacity: 0; transform: translateY(14px) scale(0.97); } }
.gmy-end { display: grid; place-items: center; height: 50px; font-size: 12.5px; color: var(--x-muted); }
.gmy-dots { display: inline-flex; gap: 4px; } .gmy-dots i { width: 6px; height: 6px; border-radius: 50%; background: var(--x-muted); animation: gx-dot2 1s infinite; } .gmy-dots i:nth-child(2) { animation-delay: 0.15s; } .gmy-dots i:nth-child(3) { animation-delay: 0.3s; }
@keyframes gx-dot2 { 50% { opacity: 0.25; } }

/* Wallet card */
.gwc-tilt { border-radius: 20px; }
.gwc { position: relative; display: block; width: min(340px, calc(100vw - 100px)); aspect-ratio: 1.586; padding: 0; border: 0; border-radius: 20px; background: none; cursor: pointer; transform-style: preserve-3d; transition: transform 0.7s cubic-bezier(0.3, 1.2, 0.4, 1); font: inherit; color: #fff; text-align: left; }
.gwc[data-flip] { transform: rotateY(180deg); }
.gwc-face { position: absolute; inset: 0; display: flex; flex-direction: column; padding: 20px 22px; border-radius: 20px; overflow: hidden; backface-visibility: hidden; -webkit-backface-visibility: hidden;
  background: radial-gradient(120% 90% at 0% 0%, color-mix(in srgb, var(--c2) 80%, #fff) 0%, transparent 55%), linear-gradient(135deg, var(--c2), var(--c1)); box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.3), 0 24px 44px -20px rgb(0 0 0 / 0.55); }
.gwc-face::after { content: ""; position: absolute; inset: 0; background: repeating-linear-gradient(115deg, transparent 0 22px, rgb(255 255 255 / 0.035) 22px 23px); pointer-events: none; }
.gwc-top { display: flex; justify-content: space-between; align-items: flex-start; }
.gwc-top b { font-size: 17px; letter-spacing: -0.01em; }
.gwc-bal { display: grid; text-align: right; font-size: 17px; font-weight: 650; } .gwc-bal em, .gwc-bot em, .gwc-cvv em { display: block; font-style: normal; font-size: 10px; font-weight: 500; letter-spacing: 0.06em; text-transform: uppercase; opacity: 0.7; }
.gwc-chip { width: 40px; height: 30px; margin-top: 14px; border-radius: 7px; background: linear-gradient(135deg, #f3d98b, #b89341); box-shadow: inset 0 0 0 1px rgb(0 0 0 / 0.15); }
.gwc-num { margin-top: auto; font: 500 clamp(15px, 4.6vw, 19px) ui-monospace, "SF Mono", Menlo, monospace; letter-spacing: 0.08em; }
.gwc-bot { display: flex; align-items: flex-end; gap: 22px; margin-top: 12px; font-size: 13px; font-weight: 600; }
.gwc-net { margin-left: auto; font-size: 19px; font-style: italic; letter-spacing: 0.02em; }
.gwc-backside { transform: rotateY(180deg); padding: 22px 0 0; }
.gwc-strip { height: 40px; background: rgb(0 0 0 / 0.75); }
.gwc-cvv { align-self: flex-end; display: grid; justify-items: end; margin: 18px 22px 0; padding: 6px 12px; border-radius: 6px; color: #17171a; background: rgb(255 255 255 / 0.9); }
.gwc-note { margin: auto 22px 18px; font-size: 12px; opacity: 0.75; }
.gwc:focus-visible { outline: 2px solid #fff; outline-offset: 4px; }

/* Not found */
.gnf { display: grid; justify-items: center; gap: 8px; max-width: 420px; padding: 24px 16px; text-align: center; color: var(--x-fg); }
.gnf-code { display: flex; align-items: center; gap: 4px; font-size: clamp(72px, 20vw, 120px); font-weight: 750; letter-spacing: -0.05em; line-height: 1; }
.gnf-code > span { display: inline-grid; place-items: center; animation: gnf-bob 3.2s ease-in-out calc(var(--k) * -0.4s) infinite; background: linear-gradient(180deg, var(--x-fg), color-mix(in srgb, var(--x-fg) 40%, transparent)); -webkit-background-clip: text; background-clip: text; color: transparent; }
.gnf-code .gnf-art { display: grid; place-items: center; width: 0.82em; height: 0.82em; }
.gnf-code .gnf-art > * { max-width: 100%; max-height: 100%; }
@keyframes gnf-bob { 50% { transform: translateY(-8px) rotate(-2deg); } }
.gnf h2 { margin: 10px 0 0; font-size: 22px; letter-spacing: -0.02em; }
.gnf p { margin: 0; font-size: 15px; color: var(--x-muted); }
.gnf-acts { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; margin-top: 12px; }

@media (prefers-reduced-motion: reduce) {
  .gmq-track { animation: none; } .gtlt-in, .gcy-drum, .gwc, .gcf-card, .gcf-front, .gms-bar, .ghh-pill, .gptr-scroll, .giv-img, .gthm *, .gthm svg { transition: none !important; }
  .gnf-code > span, .gft li, .gms-list li, .gmy-item { animation: none !important; }
}
